//! FBX fixtures (generated by `tools/fixtures/make_fbx.py`) imported into temporary projects.
#![allow(dead_code, missing_docs)]

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use concordia_assets::{AssetDb, AssetError, AssetKind, AssetRef, ImportReport, MeshData};
use concordia_core::id::{DeterministicIdGen, EntityId};
use concordia_core::math::{Mat4, Quat, Vec3};
use concordia_import_fbx::FbxImporter;
use concordia_import_model::load_prefab_doc;

pub fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/fbx")
        .join(name)
}

pub struct Project {
    pub dir: tempfile::TempDir,
    pub db: AssetDb,
}

impl Project {
    pub fn new() -> Self {
        let dir = tempfile::tempdir().unwrap();
        let mut db = AssetDb::new(dir.path(), Box::new(DeterministicIdGen::new(9))).unwrap();
        db.register(Arc::new(FbxImporter));
        Self { dir, db }
    }

    /// Copies a fixture into the project and imports it.
    pub fn fixture(&mut self, name: &str) -> Result<ImportReport, AssetError> {
        std::fs::copy(fixture(name), self.dir.path().join(name)).unwrap();
        self.db.import(Path::new(name))
    }

    /// Writes `bytes` as `name` and imports it.
    pub fn bytes(&mut self, name: &str, bytes: &[u8]) -> Result<ImportReport, AssetError> {
        std::fs::write(self.dir.path().join(name), bytes).unwrap();
        self.db.import(Path::new(name))
    }

    pub fn sub(report: &ImportReport, path: &str) -> AssetRef {
        assert!(
            report.sub_assets.contains_key(path),
            "no {path} in {:?}",
            report.sub_assets.keys()
        );
        format!("asset:{}#{path}", report.id).parse().unwrap()
    }

    pub fn load<T: serde::de::DeserializeOwned>(
        &mut self,
        report: &ImportReport,
        path: &str,
        kind: AssetKind,
    ) -> T {
        self.db.load(&Self::sub(report, path), kind).unwrap()
    }

    pub fn mesh(&mut self, report: &ImportReport, path: &str) -> MeshData {
        self.load(report, path, AssetKind::Mesh)
    }

    /// The prefab's entities with names, parents, world matrices and mesh references.
    pub fn model(&mut self, report: &ImportReport) -> Model {
        let doc = load_prefab_doc(&mut self.db, report).unwrap();
        let mut entities = BTreeMap::new();
        for e in &doc.entities {
            let json = |c: &str| e.components.get(c).map(|v| v.to_json().unwrap());
            let t = json("Transform").unwrap();
            let v3 = |k: &str| Vec3::from_slice(&floats(&t[k]));
            let local = Mat4::from_scale_rotation_translation(
                v3("scale"),
                Quat::from_slice(&floats(&t["rotation"])),
                v3("translation"),
            );
            entities.insert(
                e.id,
                Entity {
                    name: json("Name").and_then(|n| n.as_str().map(str::to_owned)),
                    parent: json("Parent").map(|p| p.as_str().unwrap().parse().unwrap()),
                    local,
                    mesh: json("MeshRenderer").map(|m| m["mesh"].as_str().unwrap().to_owned()),
                    material: json("MeshRenderer")
                        .map(|m| m["material"].as_str().unwrap().to_owned()),
                },
            );
        }
        Model { entities }
    }
}

fn floats(v: &serde_json::Value) -> Vec<f32> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap() as f32)
        .collect()
}

pub struct Entity {
    pub name: Option<String>,
    pub parent: Option<EntityId>,
    pub local: Mat4,
    pub mesh: Option<String>,
    pub material: Option<String>,
}

pub struct Model {
    pub entities: BTreeMap<EntityId, Entity>,
}

impl Model {
    pub fn id(&self, name: &str) -> EntityId {
        *self
            .entities
            .iter()
            .find(|(_, e)| e.name.as_deref() == Some(name))
            .unwrap_or_else(|| panic!("no entity named {name}"))
            .0
    }

    pub fn name(&self, id: EntityId) -> &str {
        self.entities[&id].name.as_deref().unwrap()
    }

    pub fn names(&self) -> Vec<&str> {
        self.entities
            .values()
            .filter_map(|e| e.name.as_deref())
            .collect()
    }

    /// World matrix: the parent chain's locals, root first.
    pub fn world(&self, id: EntityId) -> Mat4 {
        let e = &self.entities[&id];
        match e.parent {
            Some(p) => self.world(p) * e.local,
            None => e.local,
        }
    }

    pub fn world_of(&self, name: &str) -> Mat4 {
        self.world(self.id(name))
    }
}

pub fn close(a: [f32; 3], b: [f32; 3], eps: f32) -> bool {
    (0..3).all(|i| (a[i] - b[i]).abs() <= eps)
}

pub fn cross(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    Vec3::from_array(a).cross(Vec3::from_array(b)).to_array()
}

pub fn sub3(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    (Vec3::from_array(a) - Vec3::from_array(b)).to_array()
}

pub fn dot(a: [f32; 3], b: [f32; 3]) -> f32 {
    Vec3::from_array(a).dot(Vec3::from_array(b))
}
